struct RateWindow {
    stamps: VecDeque<Instant>,
    max: usize,
    per: Duration,
}

impl RateWindow {
    fn new(max: usize, per: Duration) -> Self {
        Self {
            stamps: VecDeque::new(),
            max,
            per,
        }
    }

    fn allow(&mut self, now: Instant) -> bool {
        while self.stamps.front().is_some_and(|&t| now - t >= self.per) {
            self.stamps.pop_front();
        }
        if self.stamps.len() >= self.max {
            return false;
        }
        self.stamps.push_back(now);
        true
    }
}

struct Limits {
    pair: Mutex<RateWindow>,
    info: Mutex<RateWindow>,
}

impl Limits {
    /// Whether a request for `path` is over its window; a poisoned lock
    /// counts as over, never as open.
    fn limited(&self, path: &str) -> bool {
        let window = match path {
            PAIR_PATH => &self.pair,
            INFO_PATH => &self.info,
            _ => return false,
        };
        !window.lock().map_or(true, |mut w| w.allow(Instant::now()))
    }
}

